    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < str.length()) {
            char nextChar = str.charAt(i + 1);
            if (nextChar == 'n') {
                sb.append('\n');
                // skip the next character to avoid double processing
                i++;
            } else if (nextChar == 't') {
                sb.append('\t');
                i++;
            } else {
                sb.append(c);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

